//! The generated ticket-pointer region of the code repository's `README.md` (`navigation.md` 3.2).
//!
//! The region is delimited by a BEGIN and an END marker line. [`apply`] replaces only the bytes
//! between them (appending the region when README has none yet), and [`check`] is the GEN001
//! comparison: the region must equal the rendering byte for byte, so a hand edit inside it is
//! reported. Everything outside the markers is hand-written and never touched.
// frob:ticket 01M3ZX87403VR4YVK4QMJ7KPBV

/// First line of the region.
pub const BEGIN: &str =
    "<!-- GENERATED by frob: BEGIN tickets. Regenerate: frob ticket reindex --code-readme -->";

/// Last line of the region.
pub const END: &str = "<!-- GENERATED by frob: END tickets -->";

/// Rule id reported by [`check`].
pub const GEN001: &str = "GEN001";

/// Where the tickets of the repository live.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Home<'a> {
    /// An orphan ticket branch of this name.
    Branch(&'a str),
    /// A directory of the code tree (trunk or branch mode).
    Dir(&'a str),
}

/// What the region is rendered from: the ticket configuration and the hosting URL.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RegionSettings<'a> {
    /// Where the tickets live.
    pub home: Home<'a>,
    /// `https://host/owner/repo`, when the repository has a web remote; links are omitted without it.
    pub web_base: Option<&'a str>,
}

/// Why a README cannot take the region.
#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
pub enum RegionError {
    /// One marker is present without the other, or END comes before BEGIN.
    #[error("README.md has an unpaired or misordered ticket region marker")]
    Unpaired,
    /// The markers appear more than once.
    #[error("README.md has more than one ticket region")]
    Duplicate,
}

/// A README whose region differs from the rendering (rule `GEN001`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RegionDrift {
    /// README has no region.
    Missing,
    /// The region exists but its bytes differ from the rendering.
    Edited,
}

impl RegionDrift {
    /// The rule id, always `GEN001`.
    #[must_use]
    pub const fn rule(self) -> &'static str {
        GEN001
    }
}

impl std::fmt::Display for RegionDrift {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Missing => write!(f, "{GEN001}: README.md has no generated tickets region"),
            Self::Edited => write!(
                f,
                "{GEN001}: the generated tickets region of README.md was edited; regenerate it with `frob ticket reindex --code-readme`"
            ),
        }
    }
}

/// Render the region, BEGIN line through END line, without a trailing newline.
#[must_use]
pub fn render(s: &RegionSettings<'_>) -> String {
    let home = match (s.home, s.web_base) {
        (Home::Branch(b), Some(base)) => {
            format!("Tickets live on the [`{b}`]({base}/tree/{b}) branch, not in this tree.")
        }
        (Home::Branch(b), None) => format!("Tickets live on the `{b}` branch, not in this tree."),
        (Home::Dir(d), _) => format!("Tickets live in [`{d}/`]({d}/)."),
    };
    let mut out = format!(
        "{BEGIN}\n## Tickets\n\n{home}\n\n```text\nfrob ticket doable   # pick a ticket\nfrob work ~HANDLE    # start it in its own worktree\nfrob land            # finish it\n```\n"
    );
    if let Some(base) = s.web_base {
        out.push_str("\nThe tracker is at [");
        out.push_str(base);
        out.push_str("/issues](");
        out.push_str(base);
        out.push_str("/issues).\n");
    }
    out.push_str(END);
    out
}

/// Byte range of the region in `readme`: BEGIN line start to END line end.
fn locate(readme: &str) -> Result<Option<(usize, usize)>, RegionError> {
    let begins: Vec<usize> = readme.match_indices(BEGIN).map(|(i, _)| i).collect();
    let ends: Vec<usize> = readme.match_indices(END).map(|(i, _)| i).collect();
    match (begins.as_slice(), ends.as_slice()) {
        ([], []) => Ok(None),
        ([b], [e]) if b < e => Ok(Some((*b, e + END.len()))),
        ([_, ..], [_, ..]) if begins.len() > 1 || ends.len() > 1 => Err(RegionError::Duplicate),
        _ => Err(RegionError::Unpaired),
    }
}

/// `readme` with its region replaced by `region`; a README without one gets it appended.
///
/// # Errors
///
/// [`RegionError`] when the markers are unpaired or repeated; nothing is guessed.
pub fn apply(readme: &str, region: &str) -> Result<String, RegionError> {
    Ok(match locate(readme)? {
        Some((start, end)) => format!("{}{region}{}", &readme[..start], &readme[end..]),
        None if readme.is_empty() => format!("{region}\n"),
        None => format!("{}\n\n{region}\n", readme.trim_end_matches('\n')),
    })
}

/// GEN001: the region of `readme` must equal `region` byte for byte.
///
/// # Errors
///
/// [`RegionDrift`] when the region is missing or edited.
pub fn check(readme: &str, region: &str) -> Result<(), RegionDrift> {
    match locate(readme) {
        Ok(Some((start, end))) if readme[start..end] == *region => Ok(()),
        Ok(None) => Err(RegionDrift::Missing),
        _ => Err(RegionDrift::Edited),
    }
}
